"""Validation summary (JSON + Markdown) and dataset manifest with checksums."""
from __future__ import annotations

import hashlib
import json
import platform
from collections import Counter
from pathlib import Path

from returns_platform.analytics.metrics import compute_metrics, coverage
from returns_platform.config import DEFAULT_POLICY_PATH
from returns_platform.domain.money import fmt_inr

PROVENANCE = {
    "data_origin": "100% synthetic, generated by returns_platform.generator from a fixed seed",
    "external_datasets_used": [],
    "personal_data": "none — names are random combinations of generic first/last names; emails use the reserved example.com domain (RFC 2606)",
    "reference_material": "Schema and policy shapes are original designs informed by common e-commerce return practices; no third-party data copied",
    "license": "Generated data may be freely redistributed with this repository",
}


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def build_manifest(out_dir: Path, files: list[Path], settings, command: str) -> dict:
    entries = []
    for p in sorted(files):
        rel = p.relative_to(out_dir).as_posix()
        rows = None
        if p.suffix == ".csv":
            with p.open("rb") as fh:
                rows = sum(1 for _ in fh) - 1
        entries.append({"path": rel, "rows": rows, "bytes": p.stat().st_size, "sha256": sha256_file(p)})
    s = settings
    return {
        "generator_command": command,
        "seed": s.seed,
        "settings": {
            "n_customers": s.n_customers, "n_products": s.n_products, "n_orders": s.n_orders,
            "n_requests": s.n_requests, "n_return_lines": s.n_return_lines,
            "first_order_date": s.first_order_date.isoformat(), "last_order_date": s.last_order_date.isoformat(),
            "as_of": s.as_of.isoformat(sep=" "), "anomalies_per_type": s.anomalies_per_type, "rates": s.rates,
        },
        "policy_file": "config/return_policy.yaml",
        "policy_sha256": sha256_file(DEFAULT_POLICY_PATH),
        "python": platform.python_version(),
        "provenance": PROVENANCE,
        "files": entries,
    }


def build_summary(suite, T, anomalies, expected, parse_errors, policy) -> dict:
    from returns_platform.validation.checks import prune_unresolvable
    T = prune_unresolvable(T)            # metrics need resolvable joins; orphans are reported by checks
    results = [r.as_dict() for r in suite.results]
    detectors = [r for r in suite.results if r.expects]
    tp = sum(r.true_pos for r in detectors)
    fp = sum(r.false_pos for r in detectors)
    fn = sum(r.false_neg for r in detectors)

    # decision accuracy: stored values vs rule-derived expected outcomes (anomalies excluded)
    rl = {x["return_line_id"]: x for x in T["return_line"]}
    anomalous_lines = set()
    for a in anomalies:
        anomalous_lines |= {a["record_id"], *a["related_ids"].split("|")}
    agree = total = 0
    for e in expected:
        if e["return_line_id"] in anomalous_lines or e["return_line_id"] not in rl:
            continue
        total += 1
        x = rl[e["return_line_id"]]
        agree += (x["decision"] == e["expected_decision"] and str(x["approved_qty"]) == str(e["expected_approved_qty"]))
    return {
        "overall_status": "PASS" if all(r.passed for r in suite.results) and not parse_errors else "FAIL",
        "checks_total": len(results),
        "checks_passed": sum(1 for r in results if r["status"] == "PASS"),
        "csv_parse_errors": parse_errors[:20],
        "anomaly_detection": {
            "ground_truth_anomalies": len(anomalies),
            "by_type": dict(Counter(a["issue_type"] for a in anomalies)),
            "true_positive": tp, "false_positive": fp, "false_negative": fn,
            "precision": round(tp / (tp + fp), 4) if tp + fp else 1.0,
            "recall": round(tp / (tp + fn), 4) if tp + fn else 1.0,
        },
        "decision_agreement_with_expected_outcomes": {"lines_compared": total, "agree": agree,
                                                      "pct": round(100 * agree / total, 2) if total else 100.0},
        "coverage": coverage(T),
        "metrics": compute_metrics(T, policy),
        "checks": results,
    }


def summary_markdown(summary: dict, manifest: dict) -> str:
    m = summary["metrics"]
    ad = summary["anomaly_detection"]
    lines = [
        "# Validation summary",
        "",
        f"**Overall: {summary['overall_status']}** — {summary['checks_passed']}/{summary['checks_total']} checks passed. "
        f"Seed `{manifest['seed']}`, policy `{m and manifest['policy_sha256'][:12]}`.",
        "",
        "A check passes when the records it flags are *exactly* the ones ground truth says it should flag: "
        "integrity checks must flag nothing; anomaly detectors must flag every labelled anomaly of their type and nothing else.",
        "",
        "## Anomaly detection vs ground truth",
        "",
        f"| Ground-truth anomalies | TP | FP | FN | Precision | Recall |",
        f"|---|---|---|---|---|---|",
        f"| {ad['ground_truth_anomalies']} | {ad['true_positive']} | {ad['false_positive']} | {ad['false_negative']} | {ad['precision']} | {ad['recall']} |",
        "",
        "By type: " + ", ".join(f"{k} = {v}" for k, v in ad["by_type"].items()),
        "",
        f"Eligibility decisions agreeing with rule-derived expected outcomes (non-anomalous lines): "
        f"**{summary['decision_agreement_with_expected_outcomes']['pct']}%** "
        f"of {summary['decision_agreement_with_expected_outcomes']['lines_compared']}.",
        "",
        "## Checks",
        "",
        "| Check | Group | Expects | Flagged | Expected | Status |",
        "|---|---|---|---|---|---|",
    ]
    for r in summary["checks"]:
        lines.append(f"| `{r['name']}` | {r['group']} | {', '.join(r['expects']) or '—'} | {r['flagged']} | {r['expected']} | {r['status']} |")
    lines += ["", "## Scenario coverage", "", "| Scenario | Count |", "|---|---|"]
    lines += [f"| {k} | {v} |" for k, v in summary["coverage"].items()]
    v, rf, inv, lc = m["volume"], m["refunds"], m["inventory"], m["lifecycle"]
    lines += [
        "", "## Key metrics", "",
        f"- Volume: {v['orders']:,} orders, {v['order_lines']:,} order lines, {v['return_requests']:,} return requests, "
        f"{v['return_lines']:,} return lines, {v['events']:,} lifecycle events.",
        f"- Return lines per 100 order lines: {m['return_rate']['return_lines_per_100_order_lines']}; "
        f"units approved {m['eligibility']['units_approved']:,} of {m['eligibility']['units_requested']:,} requested.",
        f"- Refunds: {rf['payouts']:,} payouts totalling {fmt_inr(rf['total_refunded_paise'])} "
        f"({rf['refund_pct_of_paid_on_refunded_lines']}% of amount paid on refunded lines); "
        f"fees retained {fmt_inr(rf['restocking_fees_paise'] + rf['shipping_fees_paise'])}.",
        f"- Blocked attempts: {rf['blocked_attempts']} worth {fmt_inr(rf['blocked_value_paise'])}.",
        f"- Cycle time: median request→refund {lc['median_request_to_refund_days']} days; "
        f"receipt→inspection {lc['median_receipt_to_inspection_hours']} h; inspection SLA breaches {lc['inspection_sla_breach_pct']}%.",
        f"- Inventory: {inv['sellable_units_recovered']:,} units back to sellable stock "
        f"(list value {fmt_inr(inv['recovered_list_value_paise'])}); disposition mix {inv['units_by_disposition']}.",
        "",
    ]
    return "\n".join(lines)


def write_reports(out_dir: Path, summary: dict, manifest: dict) -> None:
    (out_dir / "validation_summary.json").write_text(json.dumps(summary, indent=2, default=str) + "\n")
    (out_dir / "validation_summary.md").write_text(summary_markdown(summary, manifest))
